// ============================================================================
// Governance Check on PR — Jenkins Pipeline
// ============================================================================
// Generated by Agent: SETUP | Framework: myrmion-AI-factory
// Platform: Jenkins (Declarative Pipeline)
//
// Runs the governance gates that must pass before a PR can merge to main:
//
//   - python3 scripts/gate.py profile --run — the gate profile this PR owes (EVOL-046: one call, all members
//     report — ADR sync, law parity, budgets, retired vocabulary, currency, manifest parity, surface);
//     plus gate.py one-definition. ADR sync was the single-source-of-truth
//     gate. Bypass via [adr-backfill] commit message marker.
//
// Wire as a Multibranch Pipeline configured to build PRs (Branch Sources →
// Discover pull requests from origin). The CHANGE_TARGET env var carries the
// target branch name for PR builds.
// ============================================================================

pipeline {
  agent any

  options {
    skipDefaultCheckout(false)
  }

  stages {
    stage('Governance Check') {
      when {
        changeRequest()   // every PR — a sub-increment PR targets its train, not main (EVOL-045)
      }
      // EVOL-080: when config/quality.json → documents names a store, the documents member reads the approved artefacts kept outside the repo with a read-only service-account credential — CONFLUENCE_API_TOKEN (and CONFLUENCE_USER_EMAIL on Cloud), or each name in documents.credentials for a built store; missing or refused at the ci control point is a RED wiring finding, unless documents.verify: local (declared at SETUP) — wrap the sh step in
      // withCredentials([string(credentialsId: '<confluence-token>', variable: 'CONFLUENCE_API_TOKEN'), string(credentialsId: '<confluence-email>', variable: 'CONFLUENCE_USER_EMAIL')]) { … }
      steps {
        sh '''
          set -e
          BASE="${CHANGE_TARGET:-main}"
          git fetch origin "$BASE"
          python3 scripts/gate.py profile --run --control-point ci --base "origin/$BASE" --branch "$CHANGE_BRANCH"
          python3 scripts/gate.py one-definition
        '''
      }
    }
  }
}
